const MC_BG='data:image/jpeg;base64,';
/* ═══ 🏅 شهاداتي: شهادات الشكر التي أرسلها المعلم — يحفظها الطالب صورة أو يطبعها ═══ */
let MY_CERTS=[];
const MC_SEEN_KEY='my_certs_seen_v1';
async function myCertsLoad(){
  const box=document.getElementById('space-certs');if(!box)return;
  const sid=String(mySid||''),name=String(myName||lockedName()||'').trim();if(!sid&&!name){box.innerHTML='';return}
  let rows=[];
  try{const api=((typeof HW!=='undefined'&&HW&&HW.api)||API||'').replace(/\/+$/,'');
    const r=await fetch(api+'/my-certs?'+new URLSearchParams({sid,name}).toString(),{cache:'no-store'});const j=await r.json();rows=(j&&j.rows)||[]}catch(e){}
  if(String(mySid||'')!==sid)return;
  let hid=[];try{hid=JSON.parse(localStorage.getItem(MC_HIDE_KEY)||'[]')}catch(e){}
  rows=rows.filter(c=>!hid.includes(c.id));
  MY_CERTS=rows;
  if(!rows.length){box.innerHTML='';return}
  let seen=[];try{seen=JSON.parse(localStorage.getItem(MC_SEEN_KEY)||'[]')}catch(e){}
  const fresh=rows.filter(c=>!seen.includes(c.id));
  box.innerHTML=`<section class="mc-card">
    <div class="mc-h"><span class="mc-ic">🏅</span><div><b>شهاداتي</b><small>${rows.length} ${rows.length===1?'شهادة شكر وتقدير':'شهادات شكر وتقدير'} من معلمك</small></div></div>
    ${fresh.length?`<div class="mc-new">🎉 مبروك! وصلتك ${fresh.length===1?'شهادة جديدة':fresh.length+' شهادات جديدة'} — احفظها أو اطبعها.</div>`:''}
    <div class="mc-list">${rows.map(c=>`<div class="mc-item">
      <div class="mc-thumb" onclick="myCertOpen('${esc(c.id)}')" title="عرض الشهادة">${myCertHTML(c)}</div>
      <div class="mc-meta"><b>${esc(c.reason)}</b><small>${esc(c.date)}${mcLeft(c)}</small>
        <div class="mc-acts"><button type="button" class="mc-btn" onclick="myCertSave('${esc(c.id)}')">⬇️ حفظ صورة</button><button type="button" class="mc-btn" onclick="myCertPrint('${esc(c.id)}')">🖨️ طباعة</button><button type="button" class="mc-btn ghost" onclick="myCertHide('${esc(c.id)}')" title="إخفاؤها من صفحتي">🗑️ إخفاء</button></div></div>
    </div>`).join('')}</div>
    ${rows.some(c=>!c.paid)?'<div class="mc-note">شهادات معلمك تبقى هنا 7 أيام — احفظها صورة أو اطبعها قبل ذلك.</div>':''}</section>`;
  try{localStorage.setItem(MC_SEEN_KEY,JSON.stringify([...new Set([...seen,...rows.map(c=>c.id)])].slice(-100)))}catch(e){}
  requestAnimationFrame(()=>myCertFit(box));
}
const MC_HIDE_KEY='my_certs_hidden_v1';
/* الأيام المتبقية قبل أن تختفي الشهادة من الصفحة (7 أيام من مشاركتها) */
function mcLeft(c){ if(c.paid) return ' · من المتجر — لك دائمًا'; const d=Math.ceil((7*864e5-(Date.now()-(Number(c.at)||0)))/864e5); return d>0?` · تبقى ${d===1?'يومًا واحدًا':d===2?'يومين':d+' أيام'}`:''; }
function myCertHide(id){
  if(!confirm('إخفاء هذه الشهادة من صفحتك؟ احفظها صورة أو اطبعها أولًا إن أردت الاحتفاظ بها.')) return;
  let hid=[];try{hid=JSON.parse(localStorage.getItem(MC_HIDE_KEY)||'[]')}catch(e){}
  try{localStorage.setItem(MC_HIDE_KEY,JSON.stringify([...new Set([...hid,id])].slice(-100)))}catch(e){}
  document.getElementById('mc-view')?.remove(); myCertsLoad();
}
function myCertHTML(c){
  return `<div class="mc-cert"><img class="mc-bg" src="${MC_BG}" alt="">
    <div class="mc-pre" data-fs="2.02">${esc(c.pre)}</div><div class="mc-name"><span data-fs="2.38">${esc(c.name)}</span></div>
    <div class="mc-body"><div data-fs="1.96">وذلك نظير ${esc(c.reason)}</div><div data-fs="1.96">${esc(c.dua)}</div><div class="mc-date" data-fs="1.37">${/\d/.test(c.cls||'')?`الفصل ${esc(c.cls)} · `:''}${esc(c.date)}</div></div>
    <div class="mc-sig r"><b data-fs="1.78">${esc(c.rTitle)}</b><span data-fs="1.78">${esc(c.rName)}</span></div>
    <div class="mc-sig l"><b data-fs="1.78">${esc(c.lTitle)}</b><span data-fs="1.78">${esc(c.lName)}</span></div></div>`;
}
/* كل سطر في سطر واحد: يُصغَّر بنسبة من عرض الشهادة (cqw) فيبقى صحيحًا مصغّرًا ومكبّرًا ومطبوعًا */
function myCertFit(root){
  (root||document).querySelectorAll('.mc-cert [data-fs]').forEach(el=>{
    const base=parseFloat(el.dataset.fs)||2; let k=1, n=0; el.style.fontSize=base+'cqw';
    if(!el.clientWidth) return;
    while(el.scrollWidth>el.clientWidth+1&&k>0.4&&n++<40){ k*=0.95; el.style.fontSize=(base*k)+'cqw'; }
  });
}
function myCertOpen(id){
  const c=MY_CERTS.find(x=>x.id===id);if(!c)return;
  let ov=document.getElementById('mc-view');if(!ov){ov=document.createElement('div');ov.id='mc-view';document.body.appendChild(ov)}
  ov.innerHTML=`<div class="mc-view-in"><div class="mc-view-cert">${myCertHTML(c)}</div>
    <div class="mc-acts"><button type="button" class="mc-btn" onclick="myCertSave('${esc(id)}')">⬇️ حفظ صورة</button><button type="button" class="mc-btn" onclick="myCertPrint('${esc(id)}')">🖨️ طباعة</button><button type="button" class="mc-btn ghost" onclick="document.getElementById('mc-view').remove()">إغلاق</button></div></div>`;
  ov.onclick=e=>{if(e.target===ov)ov.remove()};
  requestAnimationFrame(()=>myCertFit(ov));
}
function myCertPrint(id){
  const c=MY_CERTS.find(x=>x.id===id);if(!c)return;
  document.getElementById('mc-print')?.remove();document.getElementById('mc-print-page')?.remove();
  const box=document.createElement('div');box.id='mc-print';box.innerHTML=myCertHTML(c);document.body.appendChild(box);
  const st=document.createElement('style');st.id='mc-print-page';st.textContent='@media print{@page{size:A4 landscape!important;margin:0!important}}';document.body.appendChild(st);
  // القياس بمقاس الورقة الفعلي قبل الطباعة (الحاوية مخفية على الشاشة)
  box.style.cssText='display:block;position:absolute;left:-20000px;top:0;width:297mm;visibility:hidden';
  box.querySelector('.mc-cert').style.width='297mm'; myCertFit(box); box.style.cssText=''; box.querySelector('.mc-cert').style.width='';
  document.body.classList.add('printing-mycert');
  const done=()=>{document.body.classList.remove('printing-mycert');box.remove();st.remove()};
  printCleanupLater(done);
  const img=box.querySelector('img');const go=()=>setTimeout(()=>{window.print()},150);
  if(img&&!img.complete)img.onload=go;else go();
}
/* حفظ صورة: الشهادة تُرسم على لوحة بدقة الطباعة ثم تُنزّل PNG — تعمل على الجوال بلا طابعة */
async function myCertSave(id){
  const c=MY_CERTS.find(x=>x.id===id);if(!c)return;
  try{await document.fonts.ready}catch(e){}
  const img=new Image();img.src=MC_BG;await new Promise(r=>{if(img.complete)r();else{img.onload=r;img.onerror=r}});
  const W=2000,H=1412,cv=document.createElement('canvas');cv.width=W;cv.height=H;const x=cv.getContext('2d');
  x.drawImage(img,0,0,W,H);x.direction='rtl';x.textAlign='center';x.textBaseline='middle';
  const F="'Readex Pro','Tajawal','Segoe UI',Tahoma,sans-serif";
  const line=(t,cx,cy,size,color,weight=800,maxW=W*0.66)=>{if(!t)return;x.fillStyle=color;let s=size;do{x.font=`${weight} ${s}px ${F}`;s-=2}while(x.measureText(t).width>maxW&&s>14);x.fillText(t,cx,cy)};
  line(c.pre,W/2,H*0.392,46,'#6E6E6E');
  x.save();x.shadowColor='rgba(0,0,0,.2)';x.shadowBlur=3;line(c.name,W/2,H*0.469,56,'#FFFFFF',800,W*0.48);x.restore();
  line('وذلك نظير '+c.reason,W/2,H*0.565,44,'#6E6E6E');
  line(c.dua,W/2,H*0.623,44,'#6E6E6E');
  line((c.cls?`الفصل ${c.cls} · `:'')+c.date,W/2,H*0.672,30,'#8A8A8A',700);
  line(c.rTitle,W*0.74,H*0.815,40,'#6E6E6E',800,W*0.26);line(c.rName,W*0.74,H*0.87,38,'#6E6E6E',700,W*0.26);
  line(c.lTitle,W*0.26,H*0.815,40,'#6E6E6E',800,W*0.26);line(c.lName,W*0.26,H*0.87,38,'#6E6E6E',700,W*0.26);
  const a=document.createElement('a');a.download=`شهادة-شكر-${(c.name||'').replace(/\s+/g,'-')}.png`;
  try{a.href=cv.toDataURL('image/png')}catch(e){alert('تعذّر حفظ الصورة — استخدم «طباعة» ثم «حفظ كـ PDF»');return}
  document.body.appendChild(a);a.click();setTimeout(()=>a.remove(),300);
}

/* ═══ 💬 راسل معلمك: سؤال أو مشكلة تصل المعلم مباشرة، ورده يظهر هنا وفي التنبيهات ═══ */
let ASK_META={cats:{activity:'سؤال عن نشاط',tech:'مشكلة في البوابة',grade:'درجة أو تصحيح',lesson:'استفسار عن الدرس',other:'أخرى'},maxLen:600,maxOpen:3}, ASK_ROWS=[];
function askApi(){ return ((typeof HW!=='undefined'&&HW&&HW.api)||API||'').replace(/\/+$/,''); }
function askWho(){ return {sid:String(mySid||''),name:String(myName||lockedName()||'').trim()}; }
function askWhen(t){ const d=Math.floor((Date.now()-t)/864e5); return d<=0?'اليوم':d===1?'أمس':d===2?'قبل يومين':d<=10?`قبل ${d} أيام`:new Date(t).toLocaleDateString('ar-SA-u-ca-gregory',{day:'numeric',month:'long'}); }
/* 💬 محادثات الطالب مع معلمه: مطوية في سطر واحد مهما كثرت.
   الرد الجديد (أول مرة يُعرض) يظهر وحده مفتوحًا حتى لا يفوت الطالب، ثم تعود مطوية. */
const ASK_UI={ open:false, more:false, exp:new Set(), fresh:new Set() };
async function myAskLoad(){
  const box=document.getElementById('space-ask'); if(!box) return;
  const w=askWho(); if(!w.sid&&!w.name){ box.innerHTML=''; return; }
  try{ const r=await fetch(askApi()+'/ask-mine?'+new URLSearchParams(w).toString(),{cache:'no-store'}); const j=await r.json();
    if(j&&j.ok){ ASK_ROWS=j.rows||[]; ASK_ROWS.forEach(x=>{ if(x.fresh) ASK_UI.fresh.add(x.id); }); if(j.keepDays) ASK_META.keepDays=j.keepDays; askDropNotices(j.gone); if(j.cats) ASK_META={...ASK_META,cats:j.cats,maxLen:j.maxLen||600,maxOpen:j.maxOpen||3}; } }catch(e){}
  if(String(mySid||'')!==w.sid) return;
  askRender();
}
function askRender(){
  const box=document.getElementById('space-ask'); if(!box) return;
  const ST={open:'⏳ بانتظار الرد',answered:'✅ ردّ معلمك',closed:'أُغلق'};
  const kd=(ASK_META.keepDays||3)*864e5;
  const rows=ASK_ROWS.filter(x=>x.status==='open'||Date.now()-(x.seenAt||x.repliedAt||x.at)<kd).sort((a,b)=>(b.repliedAt||b.at)-(a.repliedAt||a.at));
  const fresh=rows.filter(x=>ASK_UI.fresh.has(x.id)), waiting=rows.filter(x=>x.status==='open').length;
  const item=(x,full)=>`<div class="askc-it${ASK_UI.fresh.has(x.id)?' new':''}${full?' open':''}" onclick="askToggle('${esc(x.id)}',event)">
      ${x.status!=='open'?`<button type="button" class="askc-x" onclick="event.stopPropagation();askHide('${esc(x.id)}',this)" title="إخفاء" aria-label="إخفاء الرد">✕</button>`:''}
      <div class="askc-q">❓ ${esc(x.text)}</div>
      ${x.reply?`<div class="askc-r"><b>📩 ردّ المعلم:</b> ${esc(x.reply)}</div>`:''}
      <div class="askc-meta"><span class="ask-st ${esc(x.status)}">${ST[x.status]||''}</span> ${esc(ASK_META.cats[x.cat]||'')}${x.hwTitle?` · «${esc(x.hwTitle)}»`:''} · ${askWhen(x.at)}${ASK_UI.fresh.has(x.id)?'<span class="askc-new">رد جديد</span>':''}</div></div>`;
  let body='';
  if(rows.length){
    body+=`<button type="button" class="askc-sum" onclick="ASK_UI.open=!ASK_UI.open;askRender()" aria-expanded="${ASK_UI.open}"><span>📩 محادثاتك (${rows.length})</span><b>${ASK_UI.open?'إخفاء ⌃':'عرض ⌄'}</b>${fresh.length||waiting?`<span class="askc-chips">${fresh.length?`<em>${fresh.length} ${fresh.length===1?'رد جديد':'ردود جديدة'}</em>`:''}${waiting?`<i>⏳ ${waiting} بانتظار الرد</i>`:''}</span>`:''}</button>`;
    if(ASK_UI.open){
      const list=ASK_UI.more?rows:rows.slice(0,3);
      body+=`<div class="askc-list">${list.map(x=>item(x,ASK_UI.exp.has(x.id))).join('')}</div>`
        +(rows.length>3?`<button type="button" class="askc-more" onclick="ASK_UI.more=!ASK_UI.more;askRender()">${ASK_UI.more?'إخفاء الأقدم ⌃':`عرض الأقدم (${rows.length-3}) ⌄`}</button>`:'')
        +`<div class="askc-note">اضغط أي محادثة لعرضها كاملة · الرد يختفي بعد ${ASK_META.keepDays||3} أيام من قراءته، أو اضغط ✕</div>`;
    }else if(fresh.length){
      body+=`<div class="askc-list">${fresh.map(x=>item(x,true)).join('')}</div>`;
    }
  }
  box.innerHTML=`<section class="ask-card">
    <div class="ask-h"><span class="ask-ic">💬</span><div><b>عندك سؤال أو مشكلة؟</b><small>اكتب لمعلمك مباشرة — يصلك الرد هنا وعلى جوالك</small></div>
      <button type="button" class="ask-go" onclick="askOpen()">✍️ راسل معلمك</button></div>${body}
  </section>`;
}
function askToggle(id,e){ if(e&&e.target.closest('button')) return; ASK_UI.exp.has(id)?ASK_UI.exp.delete(id):ASK_UI.exp.add(id); askRender(); }
/* إخفاء الرد: يختفي من البطاقة ومن التنبيهات معًا (والسؤال يبقى محفوظًا عند المعلم) */
function askDropNotices(ids){
  (ids||[]).forEach(id=>{ const b=document.querySelector(`[data-delete-notice="msg:${CSS.escape(String(id))}"]`); if(b) b.click(); });
}
async function askHide(id,btn){
  const it=btn&&btn.closest('.askc-it,.ask-it'); if(it) it.style.opacity='.4'; if(btn) btn.disabled=true;
  try{ const r=await fetch(askApi()+'/ask-hide',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,...askWho()})});
    const j=await r.json().catch(()=>({}));
    if(!r.ok||!j.ok) throw 0;
    ASK_ROWS=ASK_ROWS.filter(x=>x.id!==id); ASK_UI.fresh.delete(id); askDropNotices(j.gone); askRender();
  }catch(e){ if(it) it.style.opacity=''; if(btn) btn.disabled=false; alert('تعذّر الإخفاء — تحقق من الإنترنت وحاول مجددًا'); }
}
function askOpen(pre){
  pre=pre||{}; document.getElementById('ask-veil')?.remove();
  const open=ASK_ROWS.filter(x=>x.status==='open').length;
  const acts=((window.__journeyRows||[]).filter(h=>h&&h.id&&!h.remedial)).slice().sort((a,b)=>(Number(b.at)||0)-(Number(a.at)||0)).slice(0,30);
  const v=document.createElement('div'); v.id='ask-veil'; v.className='ask-veil';
  v.innerHTML=`<div class="ask-sheet" role="dialog" aria-modal="true" aria-label="راسل معلمك">
    <h3>💬 راسل معلمك</h3><div class="muted" style="font-size:.8rem;line-height:1.6">رسالتك تصل معلمك وحده. اكتب بوضوح ما الذي يحصل معك، ويصلك الرد في «محادثاتك» هنا.</div>
    ${open>=ASK_META.maxOpen?`<div class="ask-err" style="margin-top:.7rem">لديك ${open} أسئلة تنتظر الرد — انتظر رد معلمك قبل إرسال سؤال جديد.</div>`:''}
    <label>نوع الرسالة</label><div class="ask-cats">${Object.entries(ASK_META.cats).map(([k,t],i)=>`<button type="button" data-k="${k}" class="${(pre.cat||'activity')===k?'on':''}">${esc(t)}</button>`).join('')}</div>
    <label for="ask-hw">النشاط (اختياري)</label><select id="ask-hw"><option value="">— بدون نشاط محدد —</option>${acts.map(h=>`<option value="${esc(h.id)}" ${pre.hw===h.id?'selected':''}>${esc(h.t||'نشاط')}</option>`).join('')}</select>
    <label for="ask-text">رسالتك</label><textarea id="ask-text" maxlength="${ASK_META.maxLen}" placeholder="مثال: في السؤال الثالث ما فهمت المطلوب… / ما يفتح معي النشاط ويطلع خطأ…"></textarea>
    <div class="ask-cnt"><span id="ask-n">0</span>/${ASK_META.maxLen}</div>
    <div class="ask-err" id="ask-err"></div>
    <div class="ask-btns"><button type="button" class="send" id="ask-send" ${open>=ASK_META.maxOpen?'disabled':''}>📨 إرسال</button><button type="button" id="ask-cancel">إلغاء</button></div>
  </div>`;
  document.body.appendChild(v);
  let cat=pre.cat||'activity';
  v.querySelectorAll('.ask-cats button').forEach(b=>b.onclick=()=>{ cat=b.dataset.k; v.querySelectorAll('.ask-cats button').forEach(x=>x.classList.toggle('on',x===b)); });
  const ta=v.querySelector('#ask-text'); ta.oninput=()=>{ v.querySelector('#ask-n').textContent=ta.value.length; };
  v.querySelector('#ask-cancel').onclick=()=>v.remove(); v.onclick=e=>{ if(e.target===v) v.remove(); };
  v.querySelector('#ask-send').onclick=async()=>{
    const text=ta.value.trim(), err=v.querySelector('#ask-err'), btn=v.querySelector('#ask-send');
    if(text.length<3){ err.textContent='اكتب رسالتك أولًا.'; ta.focus(); return; }
    btn.disabled=true; btn.textContent='⏳ جارٍ الإرسال…'; err.textContent='';
    try{ const r=await fetch(askApi()+'/ask',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...askWho(),cat,hw:v.querySelector('#ask-hw').value,text})});
      const j=await r.json().catch(()=>({}));
      if(!r.ok||!j.ok){ err.textContent=j.error||'تعذّر الإرسال — تحقق من الإنترنت وحاول مجددًا'; btn.disabled=false; btn.textContent='📨 إرسال'; return; }
      v.remove(); try{ toast('📨 وصلت رسالتك لمعلمك — سيصلك الرد في التنبيهات','good'); }catch(e){}
      myAskLoad();
    }catch(e){ err.textContent='تعذّر الإرسال — تحقق من الإنترنت وحاول مجددًا'; btn.disabled=false; btn.textContent='📨 إرسال'; }
  };
  setTimeout(()=>ta.focus(),50);
}
/* ═══ 🎯 خطتي: الطالب يعرف هدفه وأين وصل ═══ */
const MP_HIDE_KEY='my_plan_hidden_v1';
const mpKey=p=>`${p.id}:${(p.tasks||[]).length}`;
function myPlanHide(key){
  if(!confirm('إخفاء هذه البطاقة من صفحتك؟ تعود وحدها إذا أرسل لك معلمك مهمة جديدة.')) return;
  let hid=[];try{hid=JSON.parse(localStorage.getItem(MP_HIDE_KEY)||'[]')}catch(e){}
  try{localStorage.setItem(MP_HIDE_KEY,JSON.stringify([...new Set([...hid,key])].slice(-50)))}catch(e){}
  myPlanLoad();
}
async function myPlanLoad(){
  const box=document.getElementById('space-plan');if(!box)return;
  const sid=String(mySid||''),name=String(myName||lockedName()||'').trim();if(!sid&&!name){box.innerHTML='';return}
  let rows=[];
  try{const api=((typeof HW!=='undefined'&&HW&&HW.api)||API||'').replace(/\/+$/,'');
    const r=await fetch(api+'/my-plan?'+new URLSearchParams({sid,name}).toString(),{cache:'no-store'});const j=await r.json();rows=(j&&j.rows)||[]}catch(e){}
  if(String(mySid||'')!==sid)return;
  // 🙈 ما أخفاه الطالب (مثل الشهادات): المفتاح يتغيّر متى وصلته مهمة جديدة فتعود البطاقة وحدها
  let hid=[];try{hid=JSON.parse(localStorage.getItem(MP_HIDE_KEY)||'[]')}catch(e){}
  rows=rows.filter(p=>!hid.includes(mpKey(p)));
  if(!rows.length){box.innerHTML='';return}
  const ST={open:['🟡','بانتظارك'],retry:['🟠','محاولة ثانية'],mastered:['🟢','أتقنت'],escalated:['🤝','معلمك سيساعدك']};
  box.innerHTML=rows.map(p=>{
    const now=p.now, tgt=p.target||75, pct=now==null?0:Math.max(4,Math.min(100,Math.round(now/tgt*100)));
    const reached=now!=null&&now>=tgt;
    const left=p.left==null?'':p.left<0?'⏳ معلمك يراجع نتيجتك':p.left===0?'تنتهي اليوم':`باقي ${p.left} ${p.left===1?'يوم':p.left===2?'يومان':'أيام'}`;
    // 🌟 أتقن كل شيء: سطر واحد بدل الأشرطة، ويختفي وحده بعد 3 أيام
    const canHide=!(p.tasks||[]).some(t=>t.status==='open'||t.status==='retry');   // لا يُخفى ما عليه عمل فيه
    const hideBtn=canHide?`<button type="button" class="mp-hide" onclick="myPlanHide('${esc(mpKey(p))}')" title="إخفاء من صفحتي" aria-label="إخفاء من صفحتي">✕</button>`:'';
    if(p.doneAll) return `<section class="mp-card mp-done"><span class="mp-ic">🌟</span><div style="flex:1"><b>أتقنت كل مهارات خطتك العلاجية — أحسنت!</b>
      <small>${p.skills&&p.skills.length?p.skills.map(k=>esc(k.skill)).join(' · '):esc(p.reason||'')}</small></div>${hideBtn}</section>`;
    return `<section class="mp-card">
      <div class="mp-h"><span class="mp-ic">🎯</span><div style="flex:1"><b>خطتي العلاجية</b><small>${left}</small></div>${hideBtn}</div>
      ${p.skills&&p.skills.length?`<div class="mp-goal"><span>هدفي: أن أتقن كل مهارة بنسبة ${p.skillTarget||80}%</span></div>
      <div class="mp-sks">${p.skills.map(k=>{const T=p.skillTarget||80,pend=(p.tasks||[]).some(t=>t.status==='open'||t.status==='retry');
        // المقياس الرسمي: النشاط العادي بعد بدء الخطة؛ وحتى يأتي تظهر نتيجة المهمة العلاجية مؤقتًا
        const v=k.now!=null?k.now:k.rem!=null?k.rem:null, ok=v!=null&&v>=T, prov=k.now==null&&k.rem!=null, w=v==null?0:Math.max(4,Math.min(100,Math.round(v/T*100)));
        const was=k.before!=null?`كنت ${k.before}% ← `:'';
        const txt=k.now!=null?(ok?`أتقنتها ${k.now}%`:`${was}الآن ${k.now}%`)
          :prov?(ok?`${was}${k.rem}% في مهمتك العلاجية · يتأكد إتقانك في نشاطك القادم`:`${was}${k.rem}% في مهمتك العلاجية`)
          :(k.before!=null?`كنت ${k.before}% · `:'')+(pend?'حلّ مهمتك ليظهر تقدّمك':'حلّ نشاطك القادم ليظهر تقدّمك');
        return `<div class="mp-sk ${ok?(prov?'prov':'ok'):''}"><div class="mp-skh"><b>${ok?(prov?'🌟':'✅'):'🎯'} ${esc(k.skill)}</b><small>${txt}</small></div>
          <div class="mp-bar ${prov?'prov':''}"><i style="width:${w}%"></i><em style="inset-inline-start:100%"></em></div></div>`}).join('')}</div>`
      :`<div class="mp-goal">${p.goal&&p.goal.length?`<span>هدفي: إتقان</span>${p.goal.map(g=>`<span class="mp-chip">${esc(g)}</span>`).join('')}`:`<span>${esc(p.reason||'تحسين مستواي')}</span>`}</div>
      <div class="mp-prog"><div class="mp-bar"><i style="width:${pct}%"></i><em style="inset-inline-start:100%"></em></div>
        <div class="mp-nums"><span>${p.before!=null?`كنت ${p.before}%`:''}</span><b>${now==null?'حلّ نشاطك القادم ليظهر تقدّمك':reached?`🌟 وصلت ${now}% — حققت الهدف!`:`الآن ${now}% · الهدف ${tgt}%`}</b></div></div>`}
      ${p.tasks&&p.tasks.length?`<div class="mp-tasks">${p.tasks.map(t=>{const s=ST[t.status]||['⚪',t.status];return `<span class="mp-task">${s[0]} ${esc(t.title)} — ${s[1]}</span>`}).join('')}
        ${p.tasks.some(t=>t.status==='open'||t.status==='retry')?'<small class="muted">مهامك في «🎯 طوّر مستواك» أسفل الصفحة.</small>':''}</div>`:''}
    </section>`}).join('');
}
